def ex(**kw):
    return kw


FAMILIES = []


def fam(**kw):
    FAMILIES.append(kw)


# ================================================================ RBI families
RBI_PORTALS = ['RBI - CIMS (Supervisory Returns)', 'RBI - DAKSH (Supervisory Compliance)',
               'RBI - PRAVAAH (Applications / Approvals)', 'RBI (prior approval)', 'RBI (intimation)',
               'RBI - Department of Regulation', 'RBI - Department of Supervision']
COMMON_TAIL = ['FIU-IND (FINnet 2.0)', 'Credit Information Companies (CICs)', 'CERSAI / CKYCR', 'CERT-In']
END = ['Board / Management', 'Statutory / Central Auditor', 'Not Required']

PML_EXAMPLE = lambda c, d, ent: ex(
    B=1, C=c, D=d, F='Designated Director and Principal Officer - communication to FIU-IND',
    G=f'Has the {ent} appointed a Designated Director and a Principal Officer for PMLA compliance and communicated their names, designations and addresses (and any change) to the Director, FIU-IND?',
    H='Event Based', K='Rule 7(1), Prevention of Money-laundering (Maintenance of Records) Rules, 2005 read with s.12, PMLA 2002 [VERIFY rule number in current text]; corresponding KYC Directions, 2025 para [VERIFY]',
    L='A reporting entity must designate a director on its Board as the Designated Director and appoint a Principal Officer, and communicate their particulars to FIU-IND. Any change must also be intimated. The Principal Officer is responsible for furnishing reports (CTR, STR, NTR, CCR, CBWTR) to FIU-IND.',
    M='Compliance', N='PMLA, 2002 s.12; PML (Maintenance of Records) Rules, 2005; RBI KYC Directions, 2025; FIU-IND FINnet 2.0 portal', O='Compliance',
    P='FIU-IND (FINnet 2.0) — Due: on appointment and within [VERIFY] days of any change',
    Q='Failure to designate and communicate attracts action by the Director, FIU-IND under s.13 PMLA (warnings, directions, monetary penalty of ₹10,000 to ₹1 lakh per failure) and supervisory action by RBI.',
    R='High', S='Applies to every reporting entity regulated by RBI.',
    U='Board resolution designating the Director and appointing the Principal Officer; FINnet registration acknowledgement showing both officers.',
    V='Obtain a Board resolution naming the Designated Director and Principal Officer; register/update both on FINnet 2.0; keep the acknowledgement; repeat on every change.')

fam(code='RBI-SCB', name='Commercial Banks, SFBs, Payments Banks, LABs and RRBs', regulator='Reserve Bank of India', prefix='RBI_SCB',
    c_label='Bank Category (Column C)',
    C=['Commercial Bank', 'Small Finance Bank (SFB)', 'Payments Bank (PB)', 'Local Area Bank (LAB)', 'Regional Rural Bank (RRB)', 'All Banks'],
    d_label='Bank Type / Overlay (Column D)',
    D=['Public Sector Bank (PSB)', 'Private Sector Bank (Old)', 'Private Sector Bank (New)', 'Universal Bank (On-tap Licence)',
       'Foreign Bank - Branch Mode', 'Foreign Bank - Wholly Owned Subsidiary (WOS)', 'Domestic Systemically Important Bank (D-SIB)',
       'Listed Bank', 'Bank with Overseas Branches / Subsidiaries', 'Bank under Prompt Corrective Action (PCA)',
       'Small Finance Bank (SFB)', 'Payments Bank (PB)', 'Local Area Bank (LAB)', 'Regional Rural Bank (RRB)', 'All Banks (ALL)'],
    H=FREQ_EXT, M=DEPT_BASE + ['Credit', 'Internal Audit & Inspection', 'Customer Service & Grievance', 'Information Security', 'KYC & AML'],
    O=COMP_BASE, P=RBI_PORTALS + ['RBI - Foreign Exchange Department (FEMA)', 'RBI - Department of Payment & Settlement Systems', 'NABARD (ENSURE) - RRBs'] + COMMON_TAIL + ['DICGC', 'SEBI / Stock Exchanges (listed banks)', 'Ministry of Finance (DFS) - PSBs', 'MCA'] + END,
    instruments=['Banking Regulation Act, 1949; RBI Act, 1934', 'RBI (Commercial Banks – <topic>) Directions, 2025 (31 topic directions issued 28 Nov 2025, incl. Governance, Capital Adequacy, IRACP, KYC, Credit Information Reporting, Managing Risks in Outsourcing)', 'RBI (Small Finance Banks / Payments Banks / Local Area Banks / Regional Rural Banks – <topic>) Directions, 2025', 'RBI Master Direction on Information Technology Governance, Risk, Controls and Assurance Practices, 2023 [VERIFY consolidation]', 'RBI Integrated Ombudsman Scheme [VERIFY 2026 version]', 'RBI (Commercial Banks – Supervisory Returns) Directions, 2026 (RBI/DoS/2026-27/415) and SFB set (/424), 31 Jul 2026 [VERIFY numbers]'],
    example=ex(B=1, C='Commercial Bank', D='Private Sector Bank (New)', F='Board composition - special knowledge or practical experience',
               G='Does not less than fifty-one per cent of the total number of members of the Board of directors of the bank consist of persons having special knowledge or practical experience in one or more of the matters listed in section 10A(2)(a) of the Banking Regulation Act, 1949 (including at least two with agriculture/rural economy or co-operation/SSI expertise as required)?',
               H='Ongoing/Continuous', K='Section 10A(2)(a), Banking Regulation Act, 1949',
               L='Section 10A(2)(a) requires that not less than 51% of the Board consist of persons with special knowledge or practical experience in matters such as accountancy, agriculture and rural economy, banking, co-operation, economics, finance, law, small-scale industry or any other matter useful to the bank, with at least two directors having knowledge of agriculture and rural economy, co-operation or small-scale industry. The test is continuous: every appointment and cessation must be checked against it.',
               M='Governance & Administration', N='Banking Regulation Act, 1949 s.10A; RBI (Commercial Banks – Governance) Directions, 2025 [VERIFY]; Board skills matrix', O='Compliance',
               P='Board / Management', Q='Non-compliance permits RBI to reconstitute the Board under s.10A(4)–(5) and exposes the bank to supervisory action and penalty under s.46/47A BR Act.',
               R='High', S='Applies to banking companies. Applicability to SFBs/PBs/LABs follows their licensing conditions; for RRBs see the RRB Act, 1976 [VERIFY].',
               U='Board skills matrix mapped to s.10A(2)(a) categories; NRC minutes recording the check at each appointment.',
               V='Maintain a Board skills matrix against the s.10A(2)(a) categories; have the NRC test every proposed appointment and every cessation against the 51% and minimum-two rules; record the result in NRC minutes.'))

