fam(code='DATA-PRIV', name='Data Protection and Privacy (DPDP, IT Act, GDPR, CCPA)', regulator='MeitY / Data Protection Board of India; EU supervisory authorities; California Privacy Protection Agency', prefix='DATA_PRIV',
    c_label='Law / Jurisdiction (Column C)',
    C=['DPDP Act, 2023 and DPDP Rules, 2025 (India)', 'IT Act, 2000 and SPDI Rules, 2011 (India)', 'EU GDPR (EU/EEA)', 'UK GDPR and DPA 2018 (UK)', 'CCPA as amended by CPRA (California)', 'Sectoral data rules (RBI / SEBI / IRDAI / IFSCA)', 'Other jurisdiction'],
    d_label='Role (Column D)',
    D=['Data Fiduciary', 'Significant Data Fiduciary (SDF)', 'Data Processor', 'Consent Manager', 'Intermediary', 'Controller (GDPR)', 'Processor (GDPR)', 'Joint Controller (GDPR)', 'EU Representative (Art. 27)',
       'Business (CCPA)', 'Service Provider / Contractor (CCPA)', 'Third Party (CCPA)', 'Data Broker', 'Body corporate handling SPDI', 'All Roles (ALL)'],
    H=FREQ_EXT, M=DEPT_BASE + ['Privacy Office (DPO)', 'Information Security', 'Marketing', 'Customer Service & Grievance', 'Product & Engineering'], O=COMP_BASE + ['Notices & Consents'],
    P=['Data Protection Board of India', 'Affected Data Principals (intimation)', 'Consent Manager', 'CERT-In', 'Sectoral Regulator (RBI / SEBI / IRDAI / IFSCA)', 'EU / EEA Supervisory Authority (Lead SA)',
       'Affected Data Subjects (GDPR)', 'California Privacy Protection Agency / Attorney General', 'Consumers (CCPA notices)', 'Board / DPO', 'Independent Data Auditor', 'Not Required'],
    instruments=['Digital Personal Data Protection Act, 2023; DPDP Rules, 2025 (G.S.R. 846(E), 13 Nov 2025: Rules 1, 2, 17–21 in force; Rule 4 from 13 Nov 2026; Rules 3, 5–16, 22–23 from 13 May 2027)', 'Information Technology Act, 2000 s.43A, s.72A; IT (Reasonable Security Practices and SPDI) Rules, 2011 (until superseded)', 'Regulation (EU) 2016/679 (GDPR)', 'California Consumer Privacy Act, Cal. Civ. Code §1798.100 et seq., and CCPA Regulations (incl. 2025 regulations on risk assessments, cybersecurity audits and ADMT) [VERIFY effective dates]'],
    example=ex(B=1, C='DPDP Act, 2023 and DPDP Rules, 2025 (India)', D='Data Fiduciary', F='Personal data breach - intimation to the Board and Data Principals',
               G='On becoming aware of a personal data breach, does the Data Fiduciary intimate each affected Data Principal without delay, give the Board an intimation without delay, and furnish the Board a detailed report within seventy-two hours (or such longer period as the Board allows) in the manner prescribed?',
               H='Event Based', K='Section 8(6), DPDP Act, 2023; Rule 7(1) and 7(2), DPDP Rules, 2025',
               L="Section 8(6) requires the Data Fiduciary to inform the Board and each affected Data Principal of a breach. Rule 7 sets the content and timing: a concise, plain intimation to each affected Data Principal without delay (nature, extent, timing, likely consequences, mitigation, safety steps, contact); an intimation to the Board without delay; and, within 72 hours, a detailed report with facts, causes, mitigation, findings about the person responsible and remedial steps. CERT-In's six-hour reporting under the 2022 Directions runs in parallel.",
               M='Compliance', N='DPDP Act s.8(6); DPDP Rules r.7; CERT-In Directions 28 Apr 2022', O='Compliance',
               P='Data Protection Board of India — Due: intimation without delay; detailed report within 72 hours',
               Q='Failure to intimate a breach attracts a penalty of up to ₹200 crore under the Schedule to the DPDP Act (item 3).', R='High',
               S='Rules 3, 5–16 commence on 13 May 2027 (Rule 7 included). Until then, CERT-In and sectoral reporting apply.',
               U='Breach register entry; copies of Data Principal intimations; Board intimation and 72-hour report with acknowledgements.',
               V='Run the breach playbook: contain, assess, notify affected Data Principals in plain language, intimate the Board, file the detailed report within 72 hours, and file CERT-In within 6 hours where applicable.'))

